root = os.path.expanduser(sys.argv[1] if len(sys.argv) > 1 else '~/baja-apps')
if not os.path.isdir(root):
    sys.exit('Not found: ' + root)

def read(rel):
    p = os.path.join(root, rel)
    if not os.path.isfile(p):
        sys.exit('Not found: ' + p)
    # newline='' so the read does NOT translate CRLF away: with the default, the check below
    # is always False and a CRLF file would be rewritten with LF endings.
    raw = open(p, encoding='utf-8', newline='').read()
    return p, raw.replace('\r\n', '\n'), ('\r\n' in raw)

# Work everything out first; write only once every edit is known to apply.
writes = []
for rel, spec in PATCH.items():
    p, s, crlf = read(rel)
    if spec['mark'] in s:
        print('Already there:', p)
        continue
    for need, hunks in spec['paths']:
        if need is not None and need not in s:
            continue
        t, ok = s, True
        for old, new in hunks:
            if t.count(old) != 1:
                ok = False
                break
            t = t.replace(old, new, 1)
        if ok:
            writes.append((p, t, crlf))
            break
    else:
        sys.exit(p + ' differs from the version this update was made against. Nothing was changed.'
                 ' Send me that file and I will rebuild this installer against it.')

p, s, crlf = read(ANCHOR['file'])
if ANCHOR['mark'] in s:
    print('Already there:', p)
else:
    for rx, where in ANCHOR['anchors']:
        found = list(re.finditer(rx, s))
        if len(found) != 1:
            continue
        m = found[0]
        t = (s[:m.start()] + ANCHOR['item'] + m.group(0).lstrip('\n') + s[m.end():]) if where == 'before' \
            else (s[:m.end()] + ANCHOR['item'].rstrip('\n') + s[m.end():])
        writes.append((p, t, crlf))
        break
    else:
        sys.exit('Could not find the Apps menu in ' + p + '. Nothing was changed.'
                 ' Send me that file and I will rebuild this installer against it.')

for rel, text in MODULES.items():
    m = os.path.join(root, rel)
    os.makedirs(os.path.dirname(m), exist_ok=True)
    open(m, 'w', encoding='utf-8').write(text)
    print('Wrote', m)
for p, text, crlf in writes:
    shutil.copyfile(p, p + '.before-fundraise')
    open(p, 'w', encoding='utf-8', newline='').write(text.replace('\n', '\r\n') if crlf else text)
    print('Updated', p)
print('Restart baja-server (it caches scripts), then hard-refresh: Apps > Fundraise Campaign.')
